WITH paid AS(SELECT i.invoice_id,o.customer_id,i.due_date,max(a.allocation_date) last_payment_date,sum(a.amount_cents) applied_cents,i.amount_cents-coalesce((SELECT sum(c.amount_cents) FROM credit_memos c WHERE c.invoice_id=i.invoice_id AND c.credit_date<=:as_of),0) net_cents FROM invoices i JOIN orders o USING(order_id) JOIN allocations a USING(invoice_id) WHERE a.allocation_date<=:as_of AND i.recognition_date<=:as_of AND (:branch=0 OR o.branch_id=:branch) GROUP BY i.invoice_id),
late AS(SELECT customer_id,count(*) late_settled_invoices FROM paid WHERE applied_cents>=net_cents AND net_cents>0 AND last_payment_date>due_date GROUP BY customer_id),
sales AS(SELECT o.customer_id,sum(i.amount_cents) sales_cents,count(*) invoice_count FROM invoices i JOIN orders o USING(order_id) WHERE i.recognition_date BETWEEN substr(:as_of,1,4)||'-01-01' AND :as_of AND (:branch=0 OR o.branch_id=:branch) GROUP BY o.customer_id)
SELECT c.customer_id,c.name,coalesce(s.sales_cents,0) sales_cents,coalesce(s.invoice_count,0) invoice_count,coalesce(l.late_settled_invoices,0) late_settled_invoices FROM customers c LEFT JOIN sales s USING(customer_id) LEFT JOIN late l USING(customer_id) ORDER BY sales_cents DESC;
